<?php
define('RECONCILIATION_HELPERS_ONLY',true);require __DIR__.'/receipt_reconciliation.php';
function job(string $action,array $input,?string $key=null,string $service='correction',?int $actor=null):array{global $clock,$owner;return ['actor'=>$actor??$owner,'clock'=>$clock,'action'=>$action,'input'=>$input,'key'=>$key??ak(),'service'=>$service];}
function racing(array $jobs):array{$base=dirname(__DIR__,2).'/.local-setup/reconciliation-race-'.ak();$ps=[];foreach($jobs as $i=>$j){$p=proc_open([PHP_BINARY,__DIR__.'/receipt_correction_worker.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);fwrite($pipes[0],json_encode($j+['barrier'=>$base,'worker'=>$i]));fclose($pipes[0]);$ps[]=[$p,$pipes];}$until=microtime(true)+20;while(!is_file($base.'.ready0')||!is_file($base.'.ready1')){if(microtime(true)>$until)throw new RuntimeException('Worker readiness timeout');usleep(10000);}file_put_contents($base.'.go','go');$out=[];foreach($ps as [$p,$pipes]){$text=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($p)!==0||$err)throw new RuntimeException('Worker failed: '.$err);$out[]=json_decode($text,true,512,JSON_THROW_ON_ERROR);}foreach(['.ready0','.ready1','.go'] as $suffix)unlink($base.$suffix);return $out;}
function winCount(array $out):int{return count(array_filter($out,fn($x)=>$x['ok']));}
function posting(int $id):array{global $s,$owner;return ['id'=>(string)$id,'version'=>$s->detail($owner,$id)['version'],'reason'=>'Synthetic concurrent linked evidence independently checked','verified'=>'1'];}
function cashCase():array{global $staff,$f;$staff=au();$p=ap();$donor=ap('20.00');$f->execute($staff,'deposit_record',['amount'=>'500.00','fee'=>'0.00','date'=>'2043-05-15','reference'=>'RACE-'.ak()],ak());$id=ar($p,['cash_support_id'=>(string)$donor])['id'];return compact('p','donor','id');}
$x=cashCase();$in=posting($x['id']);$key=ak();$out=racing([job('post',$in,$key),job('post',$in,$key)]);aa(winCount($out)===2&&$out[0]['result']['event_id']===$out[1]['result']['event_id'],'concurrent same-key reconciliation commits one result');
$x=cashCase();$in=posting($x['id']);$out=racing([job('post',$in),job('post',$in)]);aa(winCount($out)===1,'competing approval keys cannot apply reconciliation twice');
$x=cashCase();$out=racing([job('post',posting($x['id'])),job('deposit_record',['amount'=>'20.00','fee'=>'0.00','date'=>'2043-05-15','reference'=>'RACE-DONOR-'.ak()],null,'finance',$staff)]);aa(winCount($out)===1,'supporting cash deposit and reconciliation cannot consume the same money');
$staff=au();$p=ap();$p2=ap();$donor=ap('20.00');$f->execute($staff,'deposit_record',['amount'=>'1000.00','fee'=>'0.00','date'=>'2043-05-15','reference'=>'RACE-DOUBLE-'.ak()],ak());$c1=ar($p,['cash_support_id'=>(string)$donor])['id'];$c2=ar($p2,['cash_support_id'=>(string)$donor])['id'];$out=racing([job('post',posting($c1)),job('post',posting($c2))]);aa(winCount($out)===1,'two corrections cannot reuse one supporting cash receipt');
$staff=au();$p=ap('500.00','momo');$donor=ap('20.00','momo');$f->execute($owner,'receipt_match',['id'=>(string)$p,'type'=>'payment','amount'=>'500.00','reference'=>'RACE-WALLET-'.ak(),'evidence'=>'Synthetic independent merchant proof','verified'=>'1'],ak());$id=ar($p,['wallet_support_id'=>(string)$donor])['id'];$out=racing([job('post',posting($id)),job('receipt_match',['id'=>(string)$donor,'type'=>'payment','amount'=>'20.00','reference'=>'RACE-TARGET-'.ak(),'evidence'=>'Synthetic independent target proof','verified'=>'1'],null,'finance')]);aa(winCount($out)===1,'wallet matching and allocation cannot both fill one receipt capacity');
echo "TOTAL $n reconciliation concurrency assertions passed.\n";
